steps.script:
$ErrorActionPreference='Continue'
$b='C:\TTiTTulares';$p=Join-Path $b 'image-approval-receipts'
$o=@{last2h_receipts=0;latest_receipts=@();current_generation=@();recent_statuses=@()}
$receipts=@(Get-ChildItem -LiteralPath $p -Filter '*.json' -File -ErrorAction SilentlyContinue | Where-Object {$_.Name -match '^(tr|tt)-img-'})
$o.last2h_receipts=@($receipts|Where-Object{$_.LastWriteTimeUtc -ge [datetime]::UtcNow.AddHours(-2)}).Count
$o.latest_receipts=@($receipts|Sort-Object LastWriteTimeUtc -Descending|Select-Object -First 8|ForEach-Object{@{id=$_.BaseName;utc=$_.LastWriteTimeUtc.ToString('o')}})
foreach($dir in @('ttendencias-web-images','ttittulares-web-images')){
 $path=Join-Path $b $dir
 $rows=@(Get-ChildItem $path -Filter '*.json' -File -ErrorAction SilentlyContinue|Where-Object {$_.LastWriteTimeUtc -ge [datetime]::UtcNow.AddHours(-10)}|Select-Object -First 120)
 foreach($r in $rows){try{$j=Get-Content $r.FullName -Raw|ConvertFrom-Json;if([string]$j.command_id -like '*img-auto*' -and (Get-Date $j.created_at).ToUniversalTime() -gt [datetime]::UtcNow.AddHours(-4)){$o.current_generation+=@{id=$j.command_id;state=$j.status;created=$j.created_at;reason=$j.reason}}}catch{}}
}
$st=Join-Path $p 'receiver-status.json'
if(Test-Path $st){try{$j=Get-Content $st -Raw|ConvertFrom-Json;$o.recent_statuses=@($j.PSObject.Properties|Sort-Object {$_.Value.checkedAt} -Descending|Select-Object -First 8|ForEach-Object{@{id=$_.Name;reason=$_.Value.reason}})}catch{}}
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress -Depth 5))
